        "Механично движение и отправна система: Отправна система включва отправно тяло, координатна система, свързана с него, и часовник за измерване на времето. Материална точка е модел на тяло, чиито размери могат да се пренебрегнат при разглежданото движение. Положението на материалната точка се задава с радиус-вектор r(t), а изменението му определя вектора на преместването Δr = r₂ - r₁. Пътят s е скаларна величина (дължината на описаната траектория), като винаги s ≥ |Δr|.",
        "Скорост и ускорение при праволинейно и криволинейно движение: Моментна скорост: v = lim(Δ t → 0) (Δr)/(Δ t) — насочена по допирателната към траекторията в посоката на движението. Моментно ускорение: a = lim(Δ t → 0) (Δv)/(Δ t) — при криволинейно движение се разлага на: тангенциално ускорение a(τ) (по допирателната), което изменя големината на скоростта (a(τ) = (Δ v)/(Δ t)); нормално (центростремително) ускорение a(n) (към центъра на кривината), което изменя посоката на скоростта: a(n) = (v²)/R. Пълното ускорение има големина a = √(a(τ)² + a(n)²).",
