        "Абсолютна температура, средна кинетична енергия и средна квадратична скорост: Връзка между средната кинетична енергия на постъпателното движение на молекулите и абсолютната температура T (формула на Болцман): E(k)(ср) = (m₀ v²(ср))/2 = 3/2 k T където k ≈ 1,38 · 10⁻²³ J/K е константата на Болцман. Абсолютната температура T е пряка мярка за средната кинетична енергия на хаотичното постъпателно движение на градивните частици. Като заместим E(k)(ср) = 3/2kT в p = 2/3n₀ E(k)(ср), получаваме: p = n₀ k T Средна квадратична скорост на молекулите (v(кв) = √(v²(ср))): v(кв) = √((3 k T)/m₀) = √((3 R T)/M) Тя е правопропорционална на √T и обратнопропорционална на √M.",
        "Примери и приложения: 1. Сравнение на скорости на различни газове при еднаква температура: При една и съща температура T средните кинетични енергии E(k)(ср) = 3/2kT на молекулите на водорода (M(H₂) = 2 g/mol) и кислорода (M(O₂) = 32 g/mol) са равни, но средната квадратична скорост на водородните молекули е √(32/2) = 4 пъти по-голяма от тази на кислородните. 2. Вътрешна енергия на едноатомен идеален газ: За N молекули едноатомен газ (He, Ne, Ar) вътрешната енергия е сумата от кинетичните им енергии: U = N E(k)(ср) = 3/2 N k T = 3/2 n R T = 3/2 p V."
